<script lang="ts">import { isEditingSelection, isValueSelection } from '../../../logic/selection.js';
import { isSvelteActionRenderer } from '../../../typeguards.js';
const { path, value, context, enforceString, selection, searchResultItems } = $props();
const isEditing = $derived(isValueSelection(selection) && isEditingSelection(selection));
const renderers = $derived(context.onRenderValue({
    path,
    value,
    mode: context.mode,
    truncateTextSize: context.truncateTextSize,
    readOnly: context.readOnly,
    enforceString,
    isEditing,
    parser: context.parser,
    normalization: context.normalization,
    selection,
    searchResultItems,
    onPatch: context.onPatch,
    onPasteJson: context.onPasteJson,
    onSelect: context.onSelect,
    onFind: context.onFind,
    findNextInside: context.findNextInside,
    focus: context.focus
}));
</script>

{#each renderers as renderer}
  {#if isSvelteActionRenderer(renderer)}
    {@const action = renderer.action}
    <div
      role="button"
      tabindex="-1"
      class="jse-value"
      data-type="selectable-value"
      use:action={renderer.props}
    ></div>
  {:else}
    {@const Component = renderer.component}
    <Component {...renderer.props} />
  {/if}
{/each}
